class Base {
    // VTable points to Base::vtable during Ctor/Dtor
public:
    Base() {
        vCall(); // RESOLVES TO Base::vCall
    }
    virtual void vCall() { /* Base logic */ }

    ~Base() {
        vCall(); // RESOLVES TO Base::vCall (Derived part is destroyed)
    }
};

class Derived : public Base {
public:
    Derived() {}
    void vCall() override { /* This is ignored by Base Ctor/Dtor */ }
    ~Derived() {}
};

// RULE: Virtual calls in constructors/destructors are non-virtual
// (statically bound to the current class scope).
